var engine;

async function startup({rootURI}) {
  const project = Zotero.Prefs.get("extensions.paperpileDriveBridge.projectPath", true);
  if (!project) throw new Error("Configure the bridge using the installer generated by scripts/build_drive_bridge.py.");
  const runtime = JSON.parse(await Zotero.File.getContentsAsync(project + "/.state/runtime-config.json"));
  if (runtime.project !== project) throw new Error("Rebuild the bridge after moving its project folder.");
  const scope = {Zotero, IOUtils, Services, ChromeUtils, Cc, Ci,
    PAPERPILE_RUNTIME: runtime, PAPERPILE_LOAD_ONLY: {}};
  Services.scriptloader.loadSubScript(rootURI + "import_drive_annotations.js", scope);
  Services.scriptloader.loadSubScript(rootURI + "engine.js", scope);
  engine = new scope.DriveAnnotationEngine(scope.PAPERPILE_LOAD_ONLY.importer, runtime);
  Zotero.PaperpileDriveBridge = engine;
  engine.start();
}

async function shutdown() {
  if (engine) await engine.stop();
  delete Zotero.PaperpileDriveBridge;
  engine = undefined;
}

function onMainWindowLoad({window}) { engine?.addMenu(window); }
function onMainWindowUnload({window}) { engine?.removeMenu(window); }
function install() {}
function uninstall() {}
